// ========================================
// MANUELLE PDF-LISTE - Moosburg Stadtrat
// ========================================

const pdfListe = [
  {
    url: 'https://buergerinfo-moosburg.digitalfabrix.de/getfile.asp?id=63947&type=do&smcmode=32832',
    titel: 'Stadtratssitzung Januar 2026',
    datum: '2026-01-15'
  },
  {
    url: 'https://buergerinfo-moosburg.digitalfabrix.de/getfile.asp?id=63517&type=do&smcmode=32832',
    titel: 'Stadtratssitzung Dezember 2025',
    datum: '2025-12-18'
  },
  {
    url: 'https://buergerinfo-moosburg.digitalfabrix.de/getfile.asp?id=62896&type=do&smcmode=32832',
    titel: 'Stadtratssitzung November 2025',
    datum: '2025-11-20'
  },
  {
    url: 'https://buergerinfo-moosburg.digitalfabrix.de/getfile.asp?id=62643&type=do&smcmode=32832',
    titel: 'Stadtratssitzung Oktober 2025',
    datum: '2025-10-16'
  }
];

return pdfListe.map(pdf => ({ json: pdf }));

// Speichere Metadaten
const item = $input.first();
const loopItem = $('Loop Over Items').first().json;

return [{
  json: {
    ...item.json,
    _meta: {
      titel: loopItem.titel || 'Unbekannte Sitzung',
      datum: loopItem.datum || '2025-01-01',
      url: loopItem.url || ''
    }
  },
  binary: item.binary
}];

// ========================================
// DEBUG: Zeige was aus dem PDF extrahiert wurde
// ========================================
const item = $input.first().json;

// Nach PDF-Extraktion ist der Text in 'data'
const text = item.data || item.text || '';

// Hole Metadaten aus dem vorherigen Node (Metadaten merken)
const metaNode = $('Metadaten merken').first().json;
const meta = metaNode._meta || {};

// Zeige die ersten 3000 Zeichen des extrahierten Texts
const preview = text.substring(0, 3000);

console.log('Text Länge:', text.length);
console.log('Meta:', JSON.stringify(meta));

return [{
  json: {
    _debug: {
      sitzung: meta.titel,
      datum: meta.datum,
      textLaenge: text.length,
      vorschau: preview,
      hinweis: 'Schau dir die Vorschau an!'
    },
    // Originaldaten weitergeben
    data: text,
    _meta: meta
  }
}];

const input = $input.first().json;
const aiResponse = input.message?.content || input.text || input.content || '[]';

// Hole Metadaten aus dem richtigen Node
const metaNode = $('Metadaten merken').first().json;
const meta = metaNode._meta || {};

let antraege = [];
try {
  let jsonStr = aiResponse;
  if (jsonStr.includes('```json')) jsonStr = jsonStr.split('```json')[1].split('```')[0];
  else if (jsonStr.includes('```')) jsonStr = jsonStr.split('```')[1].split('```')[0];
  const parsed = JSON.parse(jsonStr.trim());
  antraege = Array.isArray(parsed) ? parsed : [parsed];
} catch (e) {
  return [{ json: { 
    error: 'Parse Error', 
    sitzung: meta.titel,
    rawResponse: aiResponse.substring(0, 500)
  }}];
}

// Wenn keine Anträge gefunden wurden
if (antraege.length === 0) {
  return [{ json: { 
    hinweis: 'Keine Beschlüsse gefunden',
    sitzung: meta.titel,
    datum: meta.datum
  }}];
}

const result = antraege.map((a, i) => ({
  id: `crawled-${Date.now()}-${i}`,
  titel: a.titel || 'Ohne Titel',
  kurzfassung: a.kurzfassung || '',
  beschreibung: a.beschreibung || '',
  kategorie: a.kategorie || 'bau',
  status: a.status || 'angenommen',
  datum: meta.datum,
  sitzung: meta.titel,
  abstimmung: {
    dafuer: a.abstimmung?.dafuer || 0,
    dagegen: a.abstimmung?.dagegen || 0,
    abwesend: a.abstimmung?.abwesend || 0,
    details: [] // Keine erfundenen Parteistimmen!
  },
  timeline: [{ datum: meta.datum, ereignis: 'Beschluss im Stadtrat' }],
  kommentare: [],
  buergerAbstimmung: { dafuer: 0, dagegen: 0 },
  quelleUrl: meta.url
}));

return result.map(r => ({ json: r }));

// Sammle alle Ergebnisse
const alle = $input.all().map(i => i.json);
const antraege = alle.filter(a => a.id && !a.error && !a.hinweis);
const fehler = alle.filter(a => a.error || a.hinweis);

return [{ 
  json: { 
    antraege: antraege, 
    count: antraege.length, 
    fehlerOderLeer: fehler,
    crawledAt: new Date().toISOString() 
  } 
}];
